import { createContext, createEffect, createSignal, on, useContext } from "solid-js";
import { createStore } from "solid-js/store";

import ContextManager from "#core/ui/context-manager/context-manager.js";
import { OrnateFrameProps } from "#core/ui-next/components/ornate-panel.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { useLocalPlayerId } from "#core/ui-next/utilities/game-core-utilities.js";

import { AdvicePage } from "#base/ui/advice/advice-defines.js";
import getAdviceManager from "#base/ui/advice/advice-manager.js";
import PopupSequencer from "#base/ui/popup-sequencer/popup-sequencer.js";

export const AgeAdviceTags: Record<AgeType, string> = {
	[Game.getHash("AGE_ANTIQUITY")]: "ANTIQUITY",
	[Game.getHash("AGE_EXPLORATION")]: "EXPLORATION",
	[Game.getHash("AGE_MODERN")]: "MODERN",
};

interface AdvisorData {
	type: AdvisorType;
	title: string;
	pages: AdvicePage[];
}

export enum AdvicePanelTypes {
	Quote = 1,
	Message,
	Note,
	None,
}

export interface AdvisorCouncilScreenContextModel {
	clickCloseScreen: () => void;
	clickClosePopup: () => void;
	advisorInitialQuote: (title: string) => string;
	advisorsLastQuote: (advisor: AdvisorType) => string;
	advisorPortraitURL: (advisor: AdvisorType) => string;
	advisorsData: AdvisorData[];
	follow: (advisor: AdvisorType) => void;
	unfollow: (advisor: AdvisorType) => void;
	isFollowing: (advisor: AdvisorType) => boolean;
	getSelectedAdvisorCard: () => AdvisorType;
	setSelectedAdvisorCard: (advisor: AdvisorType) => void;
	getSelectedPanel: () => AdvicePanelTypes;
	setSelectedPanel: (panel: AdvicePanelTypes) => void;
	playFollowAudio: (advisor: AdvisorType) => void;
	ornatePanelData: OrnateFrameProps;
}

export function createAdvisorCouncilScreenModel() {
	const [followed, setFollowed] = createSignal<Record<AdvisorType, boolean>>({
		[AdvisorTypes.CULTURE]: getAdviceManager().isCultureFollowed(),
		[AdvisorTypes.ECONOMIC]: getAdviceManager().isEconomicFollowed(),
		[AdvisorTypes.MILITARY]: getAdviceManager().isMilitaryFollowed(),
		[AdvisorTypes.SCIENCE]: getAdviceManager().isScientificFollowed(),
	});

	const [selectedAdvisorCard, setSelectedAdvisorCard] = createSignal<AdvisorType>(AdvisorTypes.NO_ADVISOR);

	const [selectedPanel, setSelectedPanel] = createSignal<AdvicePanelTypes>(AdvicePanelTypes.None);

	const followAdvisor = (advisor: AdvisorType) => {
		switch (advisor) {
			case AdvisorTypes.CULTURE:
				getAdviceManager().setCultureFollowed(true);
				break;
			case AdvisorTypes.ECONOMIC:
				getAdviceManager().setEconomicFollowed(true);
				break;
			case AdvisorTypes.MILITARY:
				getAdviceManager().setMilitaryFollowed(true);
				break;
			case AdvisorTypes.SCIENCE:
				getAdviceManager().setScientificFollowed(true);
				break;
		}
		setFollowed((prev) => ({ ...prev, [advisor]: true }));
	};

	const unfollowAdvisor = (advisor: AdvisorType) => {
		switch (advisor) {
			case AdvisorTypes.CULTURE:
				getAdviceManager().setCultureFollowed(false);
				break;
			case AdvisorTypes.ECONOMIC:
				getAdviceManager().setEconomicFollowed(false);
				break;
			case AdvisorTypes.MILITARY:
				getAdviceManager().setMilitaryFollowed(false);
				break;
			case AdvisorTypes.SCIENCE:
				getAdviceManager().setScientificFollowed(false);
				break;
		}
		setFollowed((prev) => ({ ...prev, [advisor]: false }));
	};

	// Audio helper
	// This is not the ideal way to call these sounds, but this was
	// added to allow the controller hotkeys for follow/unfollow to work.
	const playFollowAudio = (advisor: AdvisorType) => {
		const audioTrigger = useAudio("AdvisorScreen/Button");
		switch (advisor) {
			case AdvisorTypes.CULTURE:
				audioTrigger("activate", {
					advisorType: "culture",
					following: isFollowingAdvisor(advisor) ? "true" : "false",
				});
				break;
			case AdvisorTypes.ECONOMIC:
				audioTrigger("activate", {
					advisorType: "economic",
					following: isFollowingAdvisor(advisor) ? "true" : "false",
				});
				break;
			case AdvisorTypes.MILITARY:
				audioTrigger("activate", {
					advisorType: "military",
					following: isFollowingAdvisor(advisor) ? "true" : "false",
				});
				break;
			case AdvisorTypes.SCIENCE:
				audioTrigger("activate", {
					advisorType: "science",
					following: isFollowingAdvisor(advisor) ? "true" : "false",
				});
				break;
		}
	};

	const isFollowingAdvisor = (advisor: AdvisorType) => followed()[advisor];

	function getAdvisorsData(): AdvisorData[] {
		const advisorData: AdvisorData[] = [];

		advisorData.push({
			type: AdvisorTypes.CULTURE,
			title: "CULTURE",
			pages: getAdviceManager().getCulturePages(),
		});

		advisorData.push({
			type: AdvisorTypes.ECONOMIC,
			title: "ECONOMIC",
			pages: getAdviceManager().getEconomicPages(),
		});

		advisorData.push({
			type: AdvisorTypes.MILITARY,
			title: "MILITARY",
			pages: getAdviceManager().getMilitaryPages(),
		});

		advisorData.push({
			type: AdvisorTypes.SCIENCE,
			title: "SCIENCE",
			pages: getAdviceManager().getScientificPages(),
		});

		return advisorData;
	}

	// TODO: Ideally we'd want to set this with something in the XML, rather than depend on a string concatenation pattern in the TS code.
	function getAdvisorsInitialQuote(title: string) {
		const ageTag: string = AgeAdviceTags[Game.age];
		switch (title) {
			case "CULTURE":
				return `LOC_ADVICE_${ageTag}_CULTURE_CULTURAL_VICTORY_QUOTE`;
			case "ECONOMIC":
				return `LOC_ADVICE_${ageTag}_ECONOMIC_ECONOMIC_VICTORY_QUOTE`;
			case "MILITARY":
				return `LOC_ADVICE_${ageTag}_MILITARY_MILITARY_VICTORY_QUOTE`;
			case "SCIENCE":
				return `LOC_ADVICE_${ageTag}_SCIENCE_SCIENTIFIC_VICTORY_QUOTE`;
		}
		console.error(`Advisor-Screen-Model: unable to get advisors introductory quote'${title}'.`);
		return "LOC_ADVISOR_NOTHING";
	}

	function getAdvisorsLastQuote(advisor: AdvisorType) {
		let pages: AdvicePage[] = [];
		switch (advisor) {
			case AdvisorTypes.CULTURE:
				pages = getAdviceManager().getCulturePages();
				break;
			case AdvisorTypes.ECONOMIC:
				pages = getAdviceManager().getEconomicPages();
				break;
			case AdvisorTypes.MILITARY:
				pages = getAdviceManager().getMilitaryPages();
				break;
			case AdvisorTypes.SCIENCE:
				pages = getAdviceManager().getScientificPages();
				break;
		}
		if (pages?.length) {
			const quote = pages[pages.length - 1].quote;
			return quote;
		} else {
			return Locale.compose("LOC_ADVISOR_NOTHING");
		}
	}

	function getAdvisorPortraitURL(advisor: AdvisorType): string {
		switch (advisor) {
			case AdvisorTypes.CULTURE:
				return UI.getIconURL("ADVISOR_CULTURE");
			case AdvisorTypes.ECONOMIC:
				return UI.getIconURL("ADVISOR_ECONOMIC");
			case AdvisorTypes.MILITARY:
				return UI.getIconURL("ADVISOR_MILITARY");
			case AdvisorTypes.SCIENCE:
				return UI.getIconURL("ADVISOR_SCIENCE");

			default:
				console.error(`Advisor-Screen-Model: unable to get advisr portrait URL for '${advisor}'.`);
				return "";
		}
	}

	function handleClickCloseScreen() {
		ContextManager.pop("screen-advisor-council");
	}

	function handleClickClosePopup() {
		PopupSequencer.closePopup("advisor-council-popup");
	}

	const ornatePanelData: OrnateFrameProps = {
		topIconSrc: "url(blp:radial_advisors)",
		name: "Advisor-Screen",
		id: "advisor-screen",
		backgroundImageSrc: "url(blp:bg-panel-assyria)",
	};

	const localPlayer = Players.get(GameContext.localPlayerID);
	if (localPlayer != null) {
		const playerColor = UI.Color.getPlayerColors(GameContext.localPlayerID);
		if (playerColor) {
			const variants = UI.Color.createPlayerColorVariants(playerColor);
			ornatePanelData.topIconBackgroundTint = variants.primaryColor.tintColor;
		}
	}

	const [model, setModel] = createStore<AdvisorCouncilScreenContextModel>({
		clickCloseScreen: handleClickCloseScreen,
		clickClosePopup: handleClickClosePopup,
		advisorInitialQuote: getAdvisorsInitialQuote,
		advisorsLastQuote: getAdvisorsLastQuote,
		advisorPortraitURL: getAdvisorPortraitURL,
		advisorsData: getAdvisorsData(),
		follow: followAdvisor,
		unfollow: unfollowAdvisor,
		isFollowing: isFollowingAdvisor,
		getSelectedAdvisorCard: selectedAdvisorCard,
		setSelectedAdvisorCard: setSelectedAdvisorCard,
		getSelectedPanel: selectedPanel,
		setSelectedPanel: setSelectedPanel,
		playFollowAudio: playFollowAudio,
		ornatePanelData: ornatePanelData,
	});

	/**
	 * Hotseat support, by updating content when localplayer changes.
	 */
	const localPlayerId = useLocalPlayerId();
	createEffect(
		on(
			localPlayerId,
			(playerId) => {
				// Update followed signal for the new manager instance
				setFollowed({
					[AdvisorTypes.CULTURE]: getAdviceManager().isCultureFollowed(),
					[AdvisorTypes.ECONOMIC]: getAdviceManager().isEconomicFollowed(),
					[AdvisorTypes.MILITARY]: getAdviceManager().isMilitaryFollowed(),
					[AdvisorTypes.SCIENCE]: getAdviceManager().isScientificFollowed(),
				});

				// Trigger a reactive update by mutating the solid store.
				setModel("advisorsData", getAdvisorsData());

				// Refresh the player colors which may be used by the screen.
				const currentPlayer = Players.get(playerId);
				if (currentPlayer != null) {
					const playerColor = UI.Color.getPlayerColors(playerId);
					if (playerColor) {
						const variants = UI.Color.createPlayerColorVariants(playerColor);
						setModel("ornatePanelData", "topIconBackgroundTint", variants.primaryColor.tintColor);
					}
				}
			},
			{ defer: true }, // Defer prevents this from running on the initial mount, acting just like your old engine.on listener
		),
	);

	return model;
}

export const AdvisorCouncilScreenContext = createContext<AdvisorCouncilScreenContextModel>();

export function useAdvisorScreenContext() {
	const context = useContext(AdvisorCouncilScreenContext);

	if (!context) {
		throw new Error("Unable to get advisor screen context!");
	}

	return context;
}
